def is_valid_weighted_checksum_alternating_sign(s):
    if len(s) < 2:
        return False
    body = s[:-1]
    check = s[-1]
    if not body.isdigit() or not check.isdigit():
        return False
    total = 0
    sign = 1
    for c in body:
        total += sign * int(c)
        sign *= -1
    return total % 10 == int(check)

def local_maxima_indices(lst):
