            result.append(i)
    return result

import re

def is_valid_countdown_time(s):
    m = re.fullmatch(r'(\d{2}):(\d{2}):(\d{2})', s)
    if not m:
        return False
    hh, mm, ss = m.groups()
    if not (0 <= int(mm) <= 59):
        return False
    if not (0 <= int(ss) <= 59):
        return False
    return True

def add_minutes_with_day_offset(time_str, minutes):
    h, m = map(int, time_str.split(':'))
    total = h * 60 + m + minutes
    day_offset, rem = divmod(total, 1440)
    nh, nm = divmod(rem, 60)
    return (day_offset, f'{nh:02d}:{nm:02d}')

