def is_valid_markdown_link(s):
    m = re.fullmatch(r'\[([^\]]+)\]\((\S+)\)', s)
    if not m:
        return False
    text, url = m.groups()
    if not (url.startswith('http://') or url.startswith('https://')):
        return False
    return True

