def wrap_indent_block(text, width, indent):
    words = text.split()
    lines = []
    current = []
    current_len = 0
    for word in words:
        if not current:
            current = [word]
            current_len = len(word)
        elif current_len + 1 + len(word) <= width:
            current.append(word)
            current_len += 1 + len(word)
        else:
            lines.append(' '.join(current))
            current = [word]
            current_len = len(word)
    if current:
        lines.append(' '.join(current))
    prefix = ' ' * indent
    return '\n'.join(prefix + line for line in lines)

