def suffix_max(lst):
    n = len(lst)
    if n == 0:
        return []
    result = [0] * n
    result[-1] = lst[-1]
    for i in range(n - 2, -1, -1):
        result[i] = max(lst[i], result[i + 1])
    return result

def subtract_business_days(start_day_num, n, weekend_days):
    day = start_day_num
    count = 0
    while count < n:
        day -= 1
        if day % 7 not in weekend_days:
            count += 1
    return day

