def is_valid_subnet_mask(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    octets = []
    for p in parts:
        if not p.isdigit():
            return False
        if not (1 <= len(p) <= 3):
            return False
        val = int(p)
        if not (0 <= val <= 255):
            return False
        octets.append(val)
    bits = ''.join(f'{o:08b}' for o in octets)
    zero_index = bits.find('0')
    if zero_index == -1:
        return True
    return '1' not in bits[zero_index:]

