def merge_alternately(a, b):
    result = []
    n = min(len(a), len(b))
    for i in range(n):
        result.append(a[i])
        result.append(b[i])
    if len(a) > n:
        result.append(a[n:])
    elif len(b) > n:
        result.append(b[n:])
    return ''.join(result)

def oxford_join_no_oxford(items):
